"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["8710"],{4373:function(s,a,n){n.r(a),n.d(a,{default:function(){return p}});var t=n(1147);let l=["innerHTML"],p={setup:()=>({html:""}),render:()=>((0,t.wg)(),(0,t.iD)("div",{class:"mi-doc-markdown-body",innerHTML:'<h1>搜索筛选列表页</h1>\n<div class="mi-doc-card"><h3 id="jie-shao" tabindex="-1">介绍</h3>\n<p>搜索筛选列表页适合订单列表、会员列表、内容审核列表等需要快速定位记录的移动业务页面。</p>\n<p>该场景使用 <code>NavBar</code>、<code>Search</code>、<code>Tabs</code>、<code>DropdownMenu</code>、<code>List</code>、<code>Cell</code>、<code>Tag</code> 和 <code>Empty</code> 组合出一个完整列表页骨架，包含顶部标题、关键词入口、状态切换、筛选条件、结果列表和空状态入口。</p>\n</div><div class="mi-doc-card"><h3 id="tui-jian-zu-jian" tabindex="-1">推荐组件</h3>\n<table>\n<thead>\n<tr>\n<th>组件</th>\n<th>作用</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>NavBar</td>\n<td>页面标题和返回入口</td>\n</tr>\n<tr>\n<td>Search</td>\n<td>关键词搜索入口</td>\n</tr>\n<tr>\n<td>Tabs</td>\n<td>业务状态切换</td>\n</tr>\n<tr>\n<td>DropdownMenu</td>\n<td>排序和筛选条件</td>\n</tr>\n<tr>\n<td>List</td>\n<td>结果列表容器</td>\n</tr>\n<tr>\n<td>Cell</td>\n<td>单条结果信息</td>\n</tr>\n<tr>\n<td>Tag</td>\n<td>状态标记</td>\n</tr>\n<tr>\n<td>Empty</td>\n<td>无结果反馈</td>\n</tr>\n</tbody>\n</table>\n</div><div class="mi-doc-card"><h3 id="shi-li-dai-ma" tabindex="-1">示例代码</h3>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-nav-bar</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;业务列表&quot;</span> <span class="hljs-attr">left-arrow</span> <span class="hljs-attr">left-text</span>=<span class="hljs-string">&quot;返回&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-search</span>\n    <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;keyword&quot;</span>\n    <span class="hljs-attr">shape</span>=<span class="hljs-string">&quot;round&quot;</span>\n    <span class="hljs-attr">placeholder</span>=<span class="hljs-string">&quot;搜索订单号、手机号、线索编号&quot;</span>\n    <span class="hljs-attr">show-action</span>\n/&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-tabs</span> <span class="hljs-attr">v-model:active</span>=<span class="hljs-string">&quot;activeTab&quot;</span> <span class="hljs-attr">sticky</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-tab</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;全部&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-tab</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;待处理&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-tab</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;跟进中&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-tab</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;已完成&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-tabs</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-dropdown-menu</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-dropdown-item</span> <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;sort&quot;</span> <span class="hljs-attr">:options</span>=<span class="hljs-string">&quot;sortOptions&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-dropdown-item</span> <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;channel&quot;</span> <span class="hljs-attr">:options</span>=<span class="hljs-string">&quot;channelOptions&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-dropdown-menu</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-list</span> <span class="hljs-attr">finished</span> <span class="hljs-attr">:immediate-check</span>=<span class="hljs-string">&quot;false&quot;</span> <span class="hljs-attr">finished-text</span>=<span class="hljs-string">&quot;已展示全部记录&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell</span>\n        <span class="hljs-attr">v-for</span>=<span class="hljs-string">&quot;record in records&quot;</span>\n        <span class="hljs-attr">:key</span>=<span class="hljs-string">&quot;record.title&quot;</span>\n        <span class="hljs-attr">is-link</span>\n        <span class="hljs-attr">:title</span>=<span class="hljs-string">&quot;record.title&quot;</span>\n        <span class="hljs-attr">:label</span>=<span class="hljs-string">&quot;record.label&quot;</span>\n    &gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">template</span> #<span class="hljs-attr">value</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">mi-tag</span> <span class="hljs-attr">:type</span>=<span class="hljs-string">&quot;record.type&quot;</span>&gt;</span>{{ record.value }}<span class="hljs-tag">&lt;/<span class="hljs-name">mi-tag</span>&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-list</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-empty</span> <span class="hljs-attr">image</span>=<span class="hljs-string">&quot;search&quot;</span> <span class="hljs-attr">description</span>=<span class="hljs-string">&quot;切换筛选条件后无匹配结果时展示空态&quot;</span> /&gt;</span>\n</code></pre>\n</div><div class="mi-doc-card"><h3 id="gua-yong-chang-jing" tabindex="-1">适用场景</h3>\n<ul>\n<li>订单、工单、线索、会员等移动端业务列表</li>\n<li>需要按状态、排序、时间范围快速筛选的页面</li>\n<li>需要统一加载、空态、结果展示结构的列表页</li>\n</ul>\n</div><div class="mi-doc-card"><h3 id="shi-yong-jian-yi" tabindex="-1">使用建议</h3>\n<ul>\n<li>将搜索词、状态 Tab、排序条件和接口查询参数保持一一对应。</li>\n<li>列表项只展示最关键的 2 到 3 个字段，详情信息放到下一页。</li>\n<li>无结果时保留筛选入口，避免用户只能返回重试。</li>\n</ul>\n</div>'},null,8,l))}}}]);